($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 12089328, $f$Thanks, teacher$f$, ARRAY[$f$Renstinypaws$f$]::text[], ARRAY[$f$ジョジョの奇妙な冒険 | JoJo no Kimyou na Bouken | JoJo's Bizarre Adventure$f$]::text[], NULL, ARRAY[]::text[], NULL, NULL, 1, 1, true, 1, false, $f$2018-07-14T14:38:36.998+00:00$f$, $f$2018-07-14T14:38:37.096+00:00$f$, $f$2017-09-14T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 12099570, $f$The Second Ride$f$, ARRAY[$f$BiffElderberry$f$]::text[], ARRAY[$f$Original Work$f$]::text[], NULL, ARRAY[]::text[], $f$Isenris opened his mouth to comment on it, but was interrupted by a roar across the arena. He and Ceolwin looked just in time to see Arboth swipe at the other dragon with his mighty claws. The other dragon backed away. Arboth turned, his eyes zeroing in on Isenris.$f$, 4057, 1, 1, true, 1, false, $f$2019-01-22T12:12:17.790+00:00$f$, $f$2019-01-22T12:12:17.825+00:00$f$, $f$2017-09-15T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
