($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 12187593, $f$The Calm After the Storm$f$, ARRAY[$f$Tangerine_Catnip$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$“I never thought that this-,”  Billie said, gesturing towards The Outsider and all his newfound humanity. “- was a possibility. But I didn’t drag your behind out of the centre of the void just to leave you by the side of the road. You’re welcome to stay with me as long as you want.”$f$, 24026, 5, NULL, false, -1, false, $f$2019-07-23T03:36:01.685+00:00$f$, NULL, $f$2017-10-15T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
