($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 12855726, $f$He Goes Delirious When You Kiss$f$, ARRAY[$f$adrift_me$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$Exhaustion takes over Corvo, stressful days bringing him little peace. And with every night he grows more and more restless, until one night either a feverish dream or the Outsider himself comes to relief him in a most pleasant way.$f$, 1817, 1, 1, true, 1, false, $f$2019-06-06T08:37:57.616+00:00$f$, $f$2019-06-06T08:37:57.699+00:00$f$, $f$2017-11-28T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
