($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 13140438, $f$At the Shoreline$f$, ARRAY[$f$Anonymous$f$]::text[], ARRAY[$f$Deeply Strange Deep Sea Animals$f$, $f$Anthropomorphism$f$, $f$Original Work$f$]::text[], NULL, ARRAY[]::text[], NULL, NULL, 1, 1, true, 1, false, $f$2017-12-31T00:32:57.041+00:00$f$, $f$2017-12-31T00:32:57.043+00:00$f$, $f$2017-12-25T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 13196832, $f$The Cell$f$, ARRAY[$f$songofdefiance$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$“Were you truly unaware of their presence?” the Outsider asked.  “All your years doubling as Royal Protector and Spymaster, and you never noticed them?”
“I noticed,” Corvo said.  He felt his ears burn.  “They never outwardly caused any trouble.  Nothing overt like what their lieutenants did in Karnaca.  I left them alone.  It always seemed like a better use of my time to handle the Hatters.”
“I suppose it would have,” the Outsider said.  “At least, until you learned that your daughter’s life was in danger.  Again.”$f$, 9292, 1, 1, true, 3, false, $f$2019-07-17T03:55:19.574+00:00$f$, $f$2019-07-17T03:55:19.907+00:00$f$, $f$2017-12-30T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
